51	/**
52	 * Interface for LCS solver implementations.
53	 */
54	interface LcsSolver {
55	    /**
56	     * Computes the length of the Longest Common Subsequence.
57	     *
58	     * @param input the LcsInput containing two strings
59	     * @return LcsResult with the length of the LCS
60	     */
61	    LcsResult solve(LcsInput input);
62	}
63	
64	/**
65	 * Standard dynamic programming implementation of LCS algorithm.
66	 */
67	class StandardLcsSolver implements LcsSolver {
68	    /**
69	     * Computes the length of the Longest Common Subsequence using DP.
70	     * Time complexity: O(m * n), Space complexity: O(m * n)
71	     *
72	     * @param input the LcsInput containing two strings
73	     * @return LcsResult with the length of the LCS
74	     */
75	    @Override
76	    public LcsResult solve(LcsInput input) {
77	        String s1 = input.getFirstString();
78	        String s2 = input.getSecondString();
79	
80	        int m = s1.length();
81	        int n = s2.length();
82	
83	        // Use shared DP table builder to eliminate duplication
84	        int[][] dpTable = DpTableBuilder.buildTable(s1, s2);
85	
86	        return new LcsResult(dpTable[m][n]);
87	    }
88	}
89	
90	/**
91	 * Backward-compatible wrapper maintaining original static API.
92	 */
93	class LongestCommonSubsequence {
94	    private static final LcsSolver solver = new StandardLcsSolver();
95	
96	    /**
97	     * Computes the length of the Longest Common Subsequence.
98	     * Backward-compatible convenience method using standard DP solver.
99	     *
100	     * @param s1 first string
101	     * @param s2 second string
102	     * @return length of the LCS
103	     * @throws IllegalArgumentException if either string is null
104	     */
105	    static int lcs(String s1, String s2) {
106	        LcsInput input = new LcsInput(s1, s2);
107	        return solver.solve(input).getLength();
108	    }
109	}
