1	/**
2	 * Factory for creating and composing LCS solver instances.
3	 * Provides convenient static methods for common solver configurations
4	 * and eliminates boilerplate solver instantiation patterns.
5	 */
6	class LcsSolverFactory {
7	
8	    /**
9	     * Creates a standard DP-based LCS solver.
10	     * Suitable for general-purpose use.
11	     *
12	     * Time: O(m * n), Space: O(m * n)
13	     *
14	     * @return standard LCS solver
15	     */
16	    static LcsSolver standard() {
17	        return new StandardLcsSolver();
18	    }
19	
20	    /**
21	     * Creates a space-optimized LCS solver.
22	     * Uses rolling array technique to reduce memory usage.
23	     * Suitable for memory-constrained environments.
24	     *
25	     * Time: O(m * n), Space: O(min(m, n))
26	     *
27	     * @return space-optimized LCS solver
28	     */
29	    static LcsSolver spaceOptimized() {
30	        return new SpaceOptimizedLcsSolver();
31	    }
32	
33	    /**
34	     * Creates a cached LCS solver wrapping the standard solver.
35	     * Caches results for repeated queries on same string pairs.
36	     * Useful when the same comparisons are performed multiple times.
37	     *
38	     * @return cached solver (standard + caching)
39	     */
40	    static LcsSolver cached() {
41	        return new CachedLcsSolver(new StandardLcsSolver());
42	    }
43	
44	    /**
45	     * Creates a cached LCS solver wrapping the space-optimized solver.
46	     * Combines space optimization with caching for memory-constrained scenarios
47	     * with repeated queries.
48	     *
49	     * @return cached space-optimized solver
50	     */
51	    static LcsSolver cachedSpaceOptimized() {
52	        return new CachedLcsSolver(new SpaceOptimizedLcsSolver());
53	    }
54	
55	    /**
56	     * Creates a cached solver wrapping a custom base solver.
57	     * Useful for applying caching to custom solver implementations.
58	     *
59	     * @param baseSolver the solver to wrap with caching
60	     * @return cached version of the provided solver
61	     */
62	    static LcsSolver withCaching(LcsSolver baseSolver) {
63	        return new CachedLcsSolver(baseSolver);
64	    }
65	
66	    /**
67	     * Creates a standard solver configured for use with a custom character matcher.
68	     * Enables case-insensitive, whitespace-insensitive, or custom matching logic.
69	     *
70	     * @param matcher custom character comparison strategy
71	     * @return standard solver with custom matching
72	     */
73	    static LcsSolver standardWithMatcher(CharacterMatcher matcher) {
74	        return new StandardLcsWithMatcher(matcher);
75	    }
76	
77	    /**
78	     * Gets the recommended solver for the given input size.
79	     * Automatically selects appropriate solver based on string lengths.
80	     *
81	     * Strategy:
82	     * - Small inputs (< 1000): standard solver (simplicity + good performance)
83	     * - Medium inputs (1000-10000): space-optimized (balanced)
84	     * - Large inputs (> 10000): space-optimized + caching (if repeated)
85	     *
86	     * @param estimatedSize approximate total characters in both strings
87	     * @return recommended solver
88	     */
89	    static LcsSolver recommended(int estimatedSize) {
90	        if (estimatedSize < 1000) {
91	            return standard();
92	        } else if (estimatedSize < 10000) {
93	            return spaceOptimized();
94	        } else {
95	            // For very large inputs, caching helps with related queries
96	            return cachedSpaceOptimized();
97	        }
98	    }
99	
100	    /**
101	     * Builder for constructing custom solver configurations.
102	     * Provides fluent API for composing solvers.
103	     */
104	    static class Builder {
105	        private LcsSolver baseSolver;
106	        private boolean caching = false;
107	        private CharacterMatcher matcher = null;
108	
109	        /**
110	         * Sets the base solver algorithm.
111	         *
112	         * @param type the solver type (STANDARD, SPACE_OPTIMIZED)
113	         * @return this builder
114	         */
115	        Builder withBase(SolverType type) {
116	            this.baseSolver = switch (type) {
117	                case STANDARD -> new StandardLcsSolver();
118	                case SPACE_OPTIMIZED -> new SpaceOptimizedLcsSolver();
119	            };
120	            return this;
121	        }
122	
123	        /**
124	         * Enables result caching for the solver.
125	         *
126	         * @return this builder
127	         */
128	        Builder withCaching() {
129	            this.caching = true;
130	            return this;
131	        }
132	
133	        /**
134	         * Sets a custom character matcher for the solver.
135	         *
136	         * @param characterMatcher the matching strategy
137	         * @return this builder
138	         */
139	        Builder withMatcher(CharacterMatcher characterMatcher) {
140	            this.matcher = characterMatcher;
141	            return this;
142	        }
143	
144	        /**
145	         * Builds the configured solver.
146	         *
147	         * @return the composed solver
148	         */
149	        LcsSolver build() {
150	            if (baseSolver == null) {
151	                baseSolver = new StandardLcsSolver();
152	            }
153	
154	            LcsSolver result = baseSolver;
155	
156	            // Apply matcher if specified
157	            if (matcher != null && baseSolver instanceof StandardLcsSolver) {
158	                result = new StandardLcsWithMatcher(matcher);
159	            }
160	
161	            // Apply caching last (decorates the entire chain)
162	            if (caching) {
163	                result = new CachedLcsSolver(result);
164	            }
165	
166	            return result;
167	        }
168	    }
169	
170	    /**
171	     * Creates a builder for custom solver configuration.
172	     *
173	     * @return new builder instance
174	     */
175	    static Builder builder() {
176	        return new Builder();
177	    }
178	
179	    /**
180	     * Solver type enumeration for factory selection.
181	     */
182	    enum SolverType {
183	        /**
184	         * Standard DP implementation.
185	         */
186	        STANDARD,
187	
188	        /**
189	         * Space-optimized variant.
190	         */
191	        SPACE_OPTIMIZED
192	    }
193	}
194	
195	/**
196	 * Standard LCS solver with custom character matcher support.
197	 * Internally used by factory when matcher is specified.
198	 */
199	class StandardLcsWithMatcher implements LcsSolver {
200	    private final CharacterMatcher matcher;
201	
202	    StandardLcsWithMatcher(CharacterMatcher matcher) {
203	        this.matcher = matcher;
204	    }
205	
206	    @Override
207	    public LcsResult solve(LcsInput input) {
208	        int[][] dpTable = DpTableBuilder.buildTableWithMatcher(
209	                input.getFirstString(),
210	                input.getSecondString(),
211	                matcher
212	        );
213	        return new LcsResult(dpTable[input.getFirstString().length()]
214	                [input.getSecondString().length()]);
215	    }
216	}
