1	import java.util.ArrayList;
2	import java.util.HashMap;
3	import java.util.List;
4	import java.util.Map;
5	
6	/**
7	 * Utilities for benchmarking and performance testing LCS solvers.
8	 * Enables consistent performance measurement and comparison.
9	 */
10	class BenchmarkUtils {
11	
12	    /**
13	     * Measures the execution time of an action in nanoseconds.
14	     * Includes JVM warmup to account for JIT compilation.
15	     *
16	     * @param action the code to benchmark
17	     * @return execution time in nanoseconds
18	     */
19	    static long measureNanos(Runnable action) {
20	        // Warmup: run the action multiple times to let JIT compile
21	        for (int i = 0; i < 5; i++) {
22	            action.run();
23	        }
24	
25	        // Actual measurement
26	        long startTime = System.nanoTime();
27	        action.run();
28	        long endTime = System.nanoTime();
29	
30	        return endTime - startTime;
31	    }
32	
33	    /**
34	     * Measures the execution time of an action in milliseconds.
35	     *
36	     * @param action the code to benchmark
37	     * @return execution time in milliseconds
38	     */
39	    static long measureMillis(Runnable action) {
40	        return measureNanos(action) / 1_000_000;
41	    }
42	
43	    /**
44	     * Compares relative performance of two implementations.
45	     * Returns ratio: baselineTime / subjectTime
46	     * Ratio > 1 means subject is faster
47	     * Ratio < 1 means subject is slower
48	     *
49	     * @param baseline reference implementation
50	     * @param subject  implementation to compare
51	     * @return performance ratio (baseline / subject)
52	     */
53	    static double comparePerformance(Runnable baseline, Runnable subject) {
54	        long baselineTime = measureNanos(baseline);
55	        long subjectTime = measureNanos(subject);
56	
57	        if (subjectTime == 0) return Double.POSITIVE_INFINITY;
58	        return (double) baselineTime / subjectTime;
59	    }
60	
61	    /**
62	     * Asserts that an action completes within a maximum time.
63	     * Useful for performance regression testing.
64	     *
65	     * @param action    the code to benchmark
66	     * @param maxNanos  maximum allowed execution time in nanoseconds
67	     * @throws AssertionError if action exceeds max time
68	     */
69	    static void assertPerformance(Runnable action, long maxNanos) {
70	        long actualTime = measureNanos(action);
71	        assert actualTime <= maxNanos :
72	                "Performance exceeded: " + actualTime + " ns > " + maxNanos + " ns";
73	    }
74	
75	    /**
76	     * Benchmarks a solver across multiple test cases.
77	     * Returns comprehensive performance report.
78	     *
79	     * @param solver the LCS solver to benchmark
80	     * @param testCases array of {string1, string2} pairs
81	     * @return performance report with timing information
82	     */
83	    static PerformanceReport benchmark(LcsSolver solver, TestData.TestCase[] testCases) {
84	        List<Long> timings = new ArrayList<>();
85	        long totalTime = 0;
86	
87	        for (TestData.TestCase testCase : testCases) {
88	            LcsInput input = new LcsInput(testCase.s1, testCase.s2);
89	            long time = measureNanos(() -> solver.solve(input));
90	            timings.add(time);
91	            totalTime += time;
92	        }
93	
94	        return new PerformanceReport(solver.getClass().getSimpleName(), testCases.length,
95	                                      totalTime, timings);
96	    }
97	
98	    /**
99	     * Compares performance of multiple solvers.
100	     * Returns comparative analysis with ratios and recommendations.
101	     *
102	     * @param solvers  map of solver name to solver instance
103	     * @param testCases array of {string1, string2} pairs
104	     * @return comparative performance report
105	     */
106	    static ComparativePerformanceReport compareSolvers(Map<String, LcsSolver> solvers,
107	                                                       TestData.TestCase[] testCases) {
108	        Map<String, PerformanceReport> reports = new HashMap<>();
109	
110	        for (Map.Entry<String, LcsSolver> entry : solvers.entrySet()) {
111	            reports.put(entry.getKey(), benchmark(entry.getValue(), testCases));
112	        }
113	
114	        return new ComparativePerformanceReport(reports);
115	    }
116	
117	    /**
118	     * Performance report for a single solver.
119	     */
120	    static class PerformanceReport {
121	        final String solverName;
122	        final int testCaseCount;
123	        final long totalTimeNanos;
124	        final List<Long> individualTimings;
125	
126	        PerformanceReport(String solverName, int testCaseCount, long totalTimeNanos,
127	                         List<Long> individualTimings) {
128	            this.solverName = solverName;
129	            this.testCaseCount = testCaseCount;
130	            this.totalTimeNanos = totalTimeNanos;
131	            this.individualTimings = individualTimings;
132	        }
133	
134	        /**
135	         * Gets average time per test case in nanoseconds.
136	         */
137	        long getAverageNanos() {
138	            return testCaseCount > 0 ? totalTimeNanos / testCaseCount : 0;
139	        }
140	
141	        /**
142	         * Gets average time per test case in milliseconds.
143	         */
144	        double getAverageMillis() {
145	            return getAverageNanos() / 1_000_000.0;
146	        }
147	
148	        /**
149	         * Gets minimum time observed for any test case.
150	         */
151	        long getMinNanos() {
152	            return individualTimings.stream().mapToLong(Long::longValue).min().orElse(0);
153	        }
154	
155	        /**
156	         * Gets maximum time observed for any test case.
157	         */
158	        long getMaxNanos() {
159	            return individualTimings.stream().mapToLong(Long::longValue).max().orElse(0);
160	        }
161	
162	        @Override
163	        public String toString() {
164	            return String.format(
165	                    "%s: %.3f ms avg (min: %.3f ms, max: %.3f ms, total: %.3f ms for %d cases)",
166	                    solverName,
167	                    getAverageMillis(),
168	                    getMinNanos() / 1_000_000.0,
169	                    getMaxNanos() / 1_000_000.0,
170	                    totalTimeNanos / 1_000_000.0,
171	                    testCaseCount
172	            );
173	        }
174	    }
175	
176	    /**
177	     * Comparative performance report for multiple solvers.
178	     */
179	    static class ComparativePerformanceReport {
180	        final Map<String, PerformanceReport> reports;
181	
182	        ComparativePerformanceReport(Map<String, PerformanceReport> reports) {
183	            this.reports = reports;
184	        }
185	
186	        /**
187	         * Gets the fastest solver name.
188	         */
189	        String getFastestSolver() {
190	            return reports.entrySet().stream()
191	                    .min((a, b) -> Long.compare(
192	                            a.getValue().totalTimeNanos,
193	                            b.getValue().totalTimeNanos))
194	                    .map(Map.Entry::getKey)
195	                    .orElse("Unknown");
196	        }
197	
198	        /**
199	         * Gets performance ratio of subject vs baseline.
200	         * Ratio > 1 means subject is faster.
201	         */
202	        double getSpeedup(String baseline, String subject) {
203	            PerformanceReport baselineReport = reports.get(baseline);
204	            PerformanceReport subjectReport = reports.get(subject);
205	
206	            if (baselineReport == null || subjectReport == null) return 0;
207	            if (subjectReport.totalTimeNanos == 0) return Double.POSITIVE_INFINITY;
208	
209	            return (double) baselineReport.totalTimeNanos / subjectReport.totalTimeNanos;
210	        }
211	
212	        /**
213	         * Prints comparative report to standard output.
214	         */
215	        void printReport() {
216	            System.out.println("=== Performance Report ===\n");
217	
218	            for (PerformanceReport report : reports.values()) {
219	                System.out.println(report);
220	            }
221	
222	            String fastest = getFastestSolver();
223	            System.out.println("\nFastest: " + fastest);
224	
225	            // Show speedups relative to first (baseline)
226	            String baseline = reports.keySet().iterator().next();
227	            System.out.println("\nSpeedup vs " + baseline + ":");
228	            for (String solver : reports.keySet()) {
229	                if (!solver.equals(baseline)) {
230	                    double speedup = getSpeedup(baseline, solver);
231	                    System.out.printf("  %s: %.2fx%n", solver, speedup);
232	                }
233	            }
234	        }
235	    }
236	}
