1	/**
2	 * Command-line interface for LCS computation.
3	 * Supports multiple output formats via ResultFormatter strategy.
4	 */
5	class LongestCommonSubsequenceCli {
6	
7	    // Configuration constants
8	    private static final String USAGE_MESSAGE =
9	            "Usage: java LongestCommonSubsequenceCli [--format=FORMAT] [string1] [string2]";
10	    private static final String DEFAULT_ARGS_MESSAGE =
11	            "Running with default examples (no arguments provided).";
12	    private static final String INVALID_ARGS_MESSAGE =
13	            "Invalid arguments. Expected 0 or 2-3 arguments.";
14	
15	    /**
16	     * Output format enumeration.
17	     */
18	    enum OutputFormat {
19	        SIMPLE("simple", new SimpleResultFormatter()),
20	        DETAILED("detailed", new DetailedResultFormatter()),
21	        JSON("json", new JsonResultFormatter()),
22	        CSV("csv", new CsvResultFormatter()),
23	        COMPACT("compact", new CompactResultFormatter());
24	
25	        final String name;
26	        final ResultFormatter formatter;
27	
28	        OutputFormat(String name, ResultFormatter formatter) {
29	            this.name = name;
30	            this.formatter = formatter;
31	        }
32	
33	        /**
34	         * Gets formatter for the specified format name.
35	         *
36	         * @param formatName format name (e.g., "simple", "json")
37	         * @return formatter for that format
38	         */
39	        static ResultFormatter getFormatter(String formatName) {
40	            for (OutputFormat format : OutputFormat.values()) {
41	                if (format.name.equalsIgnoreCase(formatName)) {
42	                    return format.formatter;
43	                }
44	            }
