49	    /**
50	     * Main entry point for CLI.
51	     * Usage: java LongestCommonSubsequenceCli [--format=FORMAT] [string1] [string2]
52	     * Supported formats: simple (default), detailed, json, csv, compact
53	     *
54	     * @param args command line arguments
55	     */
56	    public static void main(String[] args) {
57	        String s1;
58	        String s2;
59	        OutputFormat format = OutputFormat.SIMPLE;
60	
61	        // Parse arguments
62	        if (args.length == 0) {
