64	            s2 = TestData.EXAMPLE_S2;
65	            System.out.println(DEFAULT_ARGS_MESSAGE);
66	            System.out.println(USAGE_MESSAGE + "\n");
67	        } else if (args.length == 1 && args[0].startsWith("--format=")) {
68	            // Format specified but no strings - use defaults
69	            String formatName = args[0].substring("--format=".length());
70	            format = OutputFormat.SIMPLE;
71	            for (OutputFormat f : OutputFormat.values()) {
72	                if (f.name.equalsIgnoreCase(formatName)) {
73	                    format = f;
74	                    break;
75	                }
76	            }
77	            s1 = TestData.EXAMPLE_S1;
78	            s2 = TestData.EXAMPLE_S2;
79	        } else if (args.length == 2) {
80	            // Two args: either both strings, or format + string (error)
81	            if (args[0].startsWith("--format=")) {
82	                System.err.println("Error: Expected both strings after format option");
83	                System.err.println(USAGE_MESSAGE);
84	                System.exit(1);
85	                return;
86	            }
87	            s1 = args[0];
88	            s2 = args[1];
89	        } else if (args.length == 3) {
90	            if (!args[0].startsWith("--format=")) {
91	                System.err.println(INVALID_ARGS_MESSAGE);
92	                System.err.println(USAGE_MESSAGE);
93	                System.exit(1);
94	                return;
95	            }
96	            String formatName = args[0].substring("--format=".length());
97	            format = OutputFormat.SIMPLE;
98	            for (OutputFormat f : OutputFormat.values()) {
99	                if (f.name.equalsIgnoreCase(formatName)) {
100	                    format = f;
101	                    break;
102	                }
103	            }
104	            s1 = args[1];
105	            s2 = args[2];
106	        } else {
107	            System.err.println(INVALID_ARGS_MESSAGE);
108	            System.err.println(USAGE_MESSAGE);
109	            System.exit(1);
110	            return;
111	        }
112	
113	        try {
114	            LcsInput input = new LcsInput(s1, s2);
115	            LcsSolver solver = LcsSolverFactory.standard();
116	            LcsResult result = solver.solve(input);
117	
