4	/**
5	 * Decorator pattern implementation for caching LCS results.
6	 * Wraps any LcsSolver implementation and caches results for repeated queries.
7	 *
8	 * Useful when the same string pairs are compared multiple times.
9	 * Uses robust CacheKey class to prevent collision issues and ensure correctness
10	 * across different argument orderings.
11	 */
12	class CachedLcsSolver implements LcsSolver {
13	    private final LcsSolver delegate;
14	    private final Map<CacheKey, Integer> cache;
15	
16	    /**
17	     * Creates a cached solver wrapping the provided solver.
18	     *
19	     * @param delegate the underlying LcsSolver to cache results for
20	     */
21	    public CachedLcsSolver(LcsSolver delegate) {
22	        this.delegate = delegate;
23	        this.cache = new HashMap<>();
24	    }
25	
26	    /**
27	     * Solves LCS with caching. Returns cached result if available.
28	     * Automatically handles symmetry: lcs(A,B) and lcs(B,A) share same cache entry.
29	     *
30	     * @param input the LcsInput containing two strings
31	     * @return LcsResult with the length of the LCS (from cache if available)
32	     */
33	    @Override
34	    public LcsResult solve(LcsInput input) {
35	        CacheKey key = new CacheKey(input.getFirstString(), input.getSecondString());
36	
37	        // Check cache first (O(1) with CacheKey.equals and hashCode)
38	        if (cache.containsKey(key)) {
39	            return new LcsResult(cache.get(key));
40	        }
41	
42	        // Compute and cache the result
43	        LcsResult result = delegate.solve(input);
44	        cache.put(key, result.getLength());
45	
46	        return result;
47	    }
48	
49	    /**
50	     * Clears the cache.
51	     * Useful between independent test runs or to free memory.
52	     */
53	    public void clearCache() {
54	        cache.clear();
55	    }
56	
57	    /**
58	     * Returns the current cache size.
59	     *
60	     * @return number of entries in the cache
61	     */
62	    public int getCacheSize() {
63	        return cache.size();
64	    }
65	}
