        @Override
        public String toString() {
            return String.format(
                    "LcsAnalysis(len=%d, sim=%.1f%%, dice=%.3f, jaccard=%.3f, editDist=%d)",
                    lcsLength, similarity, dice, jaccard, editDistance
            );
        }
    }
}

